float glyph(vec2 cell,int id){
 vec2 q=(cell-vec2(0.17,0.13))/vec2(0.66,0.74);
 if(q.x<0.0||q.x>=1.0||q.y<0.0||q.y>=1.0)return 0.0;
 int x=clamp(int(floor(q.x*5.0)),0,4);
 int y=clamp(int(floor((1.0-q.y)*7.0)),0,6);
 int mask=glyphRow(id,y);
 float pixel=float((mask >> (4-x)) & 1);
