float hash21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}
mat2 rotate2(float a){float s=sin(a),c=cos(a);return mat2(c,-s,s,c);}
float lineGlow(float d,float width){return width/(abs(d)+width);}
vec3 palette(float k){return mix(u_colorA,u_colorB,clamp(k,0.0,1.0));}
void main(){
 vec2 uv=(gl_FragCoord.xy-0.5*u_resolution.xy)/max(u_resolution.y,1.0);
 float t=u_time*u_speed;
 vec2 p=uv/max(u_scale,0.3);
 float r=length(p);
 float angle=atan(p.y,p.x);
 vec3 col=vec3(0.0007,0.00045,0.0011);
 // Celestial dust, subtly orbiting the central flower.
 vec2 starUV=rotate2(t*0.012)*p*17.0;
 vec2 starCell=floor(starUV);
 vec2 starLocal=fract(starUV)-0.5;
 float star=step(0.991,hash21(starCell))*pow(max(0.0,1.0-length(starLocal)*2.0),18.0);
 col+=vec3(1.0,0.75,0.38)*star*0.22;
 // Eight recursive nested rings, each with independently evolving petal geometry.
 float fractal=0.0;
 float edges=0.0;
 float innerDetail=0.0;
 for(int i=0;i<8;i++){
  float fi=float(i);
  float radius=0.07+fi*0.068;
  float petals=8.0+fi*4.0;
  float twist=t*(0.045+fi*0.006)*(mod(fi,2.0)<1.0?1.0:-1.0);
  float theta=angle+twist+0.10*sin(t*0.25+fi*1.7);
  float folded=abs(sin(theta*petals*0.5));
  float spike=pow(folded,1.5+0.25*fi);
  float petalRadius=radius+(0.020+fi*0.002)*spike;
  float d=r-petalRadius;
  float ring=exp(-abs(d)*(125.0-fi*7.0));
  float fine=exp(-abs(d)*320.0);
  float spokes=pow(abs(cos(theta*petals*0.5)),18.0)*exp(-abs(r-radius)*30.0);
  float shimmer=0.65+0.35*sin(t*0.9+theta*3.0+fi*1.9);
  fractal+=ring*shimmer*(1.0-fi*0.065);
  edges+=fine*(0.4+0.6*spike);
  innerDetail+=spokes*0.17;
 }
 // Iterated kaleidoscopic folding gives the flower branching self-similar veins.
 vec2 z=rotate2(t*0.035)*p;
 float filigree=0.0;
 float scale=1.0;
 for(int j=0;j<6;j++){
  z=abs(z);
  if(z.x<z.y)z=z.yx;
  z=rotate2(0.785398+0.06*sin(t*0.18+float(j)))*z;
  z=z*1.67-vec2(0.42,0.16);
  scale*=1.67;
  float d=abs(length(z)-0.39)/scale;
  filigree+=exp(-d*280.0)*(0.19/float(j+1));
 }
 float petalMask=1.0-smoothstep(0.47,0.72,r);
 float breath=0.83+0.17*sin(t*0.65);
 vec3 gold=palette(0.18+0.24*sin(angle*3.0+t*0.16+u_hue*6.28318));
 vec3 bright=palette(0.70+0.22*sin(r*22.0-t*0.45));
 col+=gold*fractal*0.62*breath;
 col+=bright*edges*0.55;
 col+=mix(gold,bright,0.5)*innerDetail;
 col+=gold*filigree*petalMask*0.55;
 // Floating outer halo and bright central seed.
 float halo=exp(-abs(r-(0.60+0.012*sin(t*0.42)))*48.0);
 float aura=exp(-r*4.6)*(0.04+0.025*sin(t*0.6));
 float core=exp(-r*r*1800.0)*(1.5+0.4*sin(t*1.1));
 col+=bright*halo*0.15;
 col+=gold*aura;
 col+=vec3(1.0,0.97,0.84)*core;
 // Soft high dynamic range glow; no external textures or extra uniforms.
 float bloom=exp(-abs(r-0.32)*7.0)*0.04;
 col+=gold*bloom*(0.4+0.6*sin(t*0.22)*sin(t*0.22));
 col=vec3(1.0)-exp(-col*max(u_glow,0.0)*1.3);
 col=pow(max(col,vec3(0.0)),vec3(0.90));
 fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

precision highp float;
uniform vec2 u_resolution;
uniform float u_time, u_speed, u_glow, u_hue, u_scale;
uniform vec3 u_colorA, u_colorB;
out vec4 fragColor;
float hash(float x){return fract(sin(x*127.17+19.19)*43758.5453);}
float glyph(vec2 p,float seed){
  vec2 q=floor(p*vec2(5.0,7.0));
  if(q.x<0.0||q.x>4.0||q.y<0.0||q.y>6.0)return 0.0;
  float bits=hash(seed*17.3+q.x*7.1+q.y*19.7);
  float frame=step(0.18,hash(seed+q.y*3.9))*step(0.26,bits);
  float bar=step(0.79,hash(seed*2.7+q.y*11.0))*step(1.0,q.x)*step(q.x,3.0);
  return max(frame,bar);
}
void main(){
 vec2 uv=gl_FragCoord.xy/max(u_resolution.xy,vec2(1.0));
 vec2 p=(gl_FragCoord.xy-0.5*u_resolution.xy)/max(u_resolution.y,1.0);
 float t=u_time*u_speed;
 vec3 col=vec3(0.003,0.00025,0.0005);
 float gridX=uv.x*46.0/max(u_scale,0.3);
 float lane=floor(gridX);
 float lx=fract(gridX);
 float variation=hash(lane+17.0);
 float velocity=0.35+variation*0.9;
 float pos=uv.y*35.0/max(u_scale,0.3)+t*velocity*5.0+variation*97.0;
 float row=floor(pos);
 float ly=fract(pos);
 float head=fract(t*velocity*0.12+variation);
 float headRow=floor(head*35.0/max(u_scale,0.3));
 float dist=mod(headRow-row+350.0,35.0/max(u_scale,0.3));
 float tail=exp(-dist*0.22)*step(dist,23.0);
 float chance=step(0.16,hash(lane*23.7+row*13.1));
 float seed=hash(lane*17.0+row*7.0+floor(t*0.45));
 vec2 gp=(vec2(lx,ly)-vec2(0.15,0.12))/vec2(0.70,0.76);
 float letter=glyph(gp,seed*200.0)*chance;
 float pixelMask=step(0.05,fract(gp.x*5.0))*step(0.05,fract(gp.y*7.0));
 float code=letter*pixelMask*tail;
 vec3 red=mix(u_colorA,u_colorB,clamp(variation*0.5+u_hue*0.5,0.0,1.0));
 col+=red*code*(0.65+u_glow*0.32);
 col+=red*tail*0.045*u_glow;
 float brightHead=exp(-dist*1.7)*letter;
 col+=vec3(1.0,0.45,0.38)*brightHead*1.3;
 // Distinctive intrusion scan: moving segmented crimson diagnostic bands.
 float scanY=fract(uv.y*1.8-t*0.11);
 float band=exp(-abs(scanY-0.5)*110.0);
 float segments=step(0.27,hash(floor(uv.x*23.0)+floor(t*2.0)*5.0));
 col+=u_colorA*band*segments*(0.15+u_glow*0.22);
 // Horizontal interference tears and corrupted blocks.
 float tearRow=floor(uv.y*110.0);
 float glitch=step(0.982,hash(tearRow+floor(t*7.0)*43.0));
 float pulse=0.5+0.5*sin(t*3.0+uv.y*24.0);
 col+=u_colorB*glitch*pulse*0.075;
 float scanline=0.88+0.12*sin(gl_FragCoord.y*2.1);
 float vignette=1.0-smoothstep(0.25,0.9,length(p));
 col*=scanline*(0.4+0.6*vignette);
 col=1.0-exp(-col);
 fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

precision highp float;
uniform vec2 u_resolution;
uniform float u_time, u_speed, u_glow, u_hue, u_scale;
uniform vec3 u_colorA, u_colorB;
out vec4 fragColor;
float hash1(float n){return fract(sin(n*127.1+78.233)*43758.5453);}
vec2 hash2(vec2 p){return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);}
float segDist(vec2 p,vec2 a,vec2 b){vec2 v=b-a;return length(p-a-v*clamp(dot(p-a,v)/max(dot(v,v),0.00001),0.0,1.0));}
float pulse(float x,float center,float width){return exp(-pow((x-center)/width,2.0));}
void main(){
 vec2 uv=(gl_FragCoord.xy-0.5*u_resolution.xy)/max(u_resolution.y,1.0);
 vec2 p=uv*6.0/max(u_scale,0.3);
 float t=u_time*u_speed;
 vec3 col=vec3(0.0015,0.0005,0.009);
 float fog=exp(-length(uv)*2.1);
 col+=mix(u_colorA,u_colorB,0.5)*fog*0.018;
 // Three independently drifting neural planes, each connecting neighboring neuron nodes.
 for(int layer=0;layer<3;layer++){
  float z=float(layer);
  vec2 q=p*(0.85+z*0.38)+vec2(sin(t*0.09+z)*0.24,t*(0.035+z*0.018));
  vec2 base=floor(q);
  vec2 f=fract(q);
  for(int iy=-1;iy<=1;iy++){
   for(int ix=-1;ix<=1;ix++){
    vec2 id=base+vec2(float(ix),float(iy));
    vec2 h=hash2(id+z*37.0);
    vec2 a=vec2(float(ix),float(iy))+0.5+(h-0.5)*0.53;
    a+=0.09*sin(vec2(t*0.38+h.x*6.28,t*0.29+h.y*6.28));
    float nodeDist=length(f-a);
    float node=exp(-nodeDist*24.0)+0.32*exp(-nodeDist*8.0);
    vec3 tint=mix(u_colorA,u_colorB,fract(h.x*0.7+u_hue+z*0.17));
    float shimmer=0.65+0.35*sin(t*1.8+dot(id,vec2(2.2,3.7)));
    col+=tint*node*shimmer*(0.11+z*0.035)*u_glow;
    // Connections are drawn once from each node, to its right and upward neighbors.
    for(int dir=0;dir<2;dir++){
     vec2 stepv=dir==0?vec2(1.0,0.0):vec2(0.0,1.0);
     vec2 hid=hash2(id+stepv+z*37.0);
     vec2 b=vec2(float(ix),float(iy))+stepv+0.5+(hid-0.5)*0.53;
     b+=0.09*sin(vec2(t*0.38+hid.x*6.28,t*0.29+hid.y*6.28));
     vec2 v=b-a;
     float len2=max(dot(v,v),0.00001);
     float along=clamp(dot(f-a,v)/len2,0.0,1.0);
     float d=segDist(f,a,b);
     float valid=step(0.18,hash1(dot(id,vec2(17.0,53.0))+float(dir)*11.0+z*31.0));
     float filament=exp(-d*110.0)*0.34+exp(-d*21.0)*0.065;
     float phase=fract(t*(0.31+0.09*z)+hash1(dot(id,vec2(7.3,13.9))+float(dir)*29.0)*1.0);
     float packet=pulse(along,phase,0.085)*exp(-d*52.0);
     float wake=exp(-d*42.0)*exp(-max(0.0,phase-along)*12.0)*step(along,phase)*0.15;
     col+=tint*(filament+packet*1.45+wake)*valid*(0.55+z*0.14)*u_glow;
     col+=vec3(0.82,0.65,1.0)*packet*valid*0.52*u_glow;
    }
   }
  }
 }
 // Sparse ultraviolet synaptic flashes and subtle horizontal electrical interference.
 float flash=pow(max(0.0,sin(t*2.7+sin(p.x*2.1)*3.0+p.y*0.8)),24.0);
 col+=u_colorB*flash*0.025*fog*u_glow;
 float scan=0.985+0.015*sin(gl_FragCoord.y*1.65+t*3.0);
 col*=scan;
 col=vec3(1.0)-exp(-col*1.25);
 fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

precision highp float;
uniform vec2 u_resolution;
uniform float u_time, u_speed, u_glow, u_hue, u_scale;
uniform vec3 u_colorA, u_colorB;
out vec4 fragColor;

float hash(float n){return fract(sin(n*127.1+78.233)*43758.5453123);}
float hash2(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}
float sdBox(vec2 p,vec2 b){vec2 q=abs(p)-b;return length(max(q,0.0))+min(max(q.x,q.y),0.0);}
float circle(vec2 p,vec2 c,float r){return length(p-c)-r;}
float ellipse(vec2 p,vec2 c,vec2 r){return (length((p-c)/r)-1.0)*min(r.x,r.y);}
float skullShape(vec2 p){
 float cr=ellipse(p,vec2(0.0,0.19),vec2(0.47,0.54));
 float temple=sdBox(p-vec2(0.0,-0.18),vec2(0.34,0.29));
 float jaw=sdBox(p-vec2(0.0,-0.42),vec2(0.275,0.20));
 return min(cr,min(temple,jaw));
}
float skullMask(vec2 p){
 float d=skullShape(p);
 float eyeL=ellipse(p,vec2(-0.205,0.045),vec2(0.155,0.135));
 float eyeR=ellipse(p,vec2(0.205,0.045),vec2(0.155,0.135));
 float nose=max(abs(p.x)*0.95+p.y*0.45-0.073,-p.y-0.015);
 float holes=min(min(eyeL,eyeR),nose);
 float shell=1.0-smoothstep(-0.009,0.009,d);
 shell*=smoothstep(-0.012,0.013,holes);
 return shell;
}
float glyph(vec2 p,float seed){
 vec2 q=p-0.5;
 float a=step(abs(q.x),0.32)*step(abs(q.y),0.38);
 float v=step(0.25,hash(seed+2.0));
 float bars=step(abs(q.x-0.17*sin(seed)),0.09)+step(abs(q.y-0.17*cos(seed*1.7)),0.075);
 return a*v*min(1.0,bars);
}
void main(){
 vec2 uv=gl_FragCoord.xy/max(u_resolution,vec2(1.0));
 vec2 p=(gl_FragCoord.xy-0.5*u_resolution.xy)/max(u_resolution.y,1.0);
 p/=max(u_scale,0.3);
 float t=u_time*u_speed;
 vec3 red=mix(u_colorA,u_colorB,clamp(u_hue,0.0,1.0)*0.7);
 vec3 col=vec3(0.0015,0.00015,0.00035);
 // Three layers of downward-moving, procedurally encoded columns.
 for(int layer=0;layer<3;layer++){
  float l=float(layer);
  float density=20.0+l*10.0;
  vec2 q=p*density;
  float column=floor(q.x);
  float velocity=0.9+hash(column*4.13+l*19.0)*1.8;
  float y=q.y+t*velocity*4.5;
  vec2 cell=floor(vec2(q.x,y));
  vec2 f=fract(vec2(q.x,y));
  float symbol=glyph(f,hash2(cell+vec2(l*71.0,0.0))*61.0);
  float head=fract(t*velocity*0.22+hash(column+l*47.0));
  float trail=exp(-mod(head-fract(y*0.018)+1.0,1.0)*8.0);
  float gate=step(0.30,hash(column*1.73+l*17.0));
  float strength=(0.012+0.018*l)*gate*trail;
  col+=red*symbol*strength;
 }
 // Skull exists as fragmented illuminated code, not a static photograph.
 vec2 s=p;
 float band=floor((s.y+t*0.05)*39.0);
 float corrupt=step(0.84,hash(band+floor(t*7.0)*13.0));
 s.x+=(hash(band*3.0+floor(t*11.0))-0.5)*0.12*corrupt;
 float mask=skullMask(s);
 float outline=exp(-abs(skullShape(s))*38.0);
 float scan=0.55+0.45*sin(s.y*115.0-t*8.0);
 float breakage=step(0.17,hash2(floor(s*vec2(95.0,105.0))+floor(t*3.0)*vec2(1.0,3.0)));
 float appear=0.82+0.18*sin(t*1.2);
 float skullLight=mask*breakage*(0.18+0.48*scan)*appear;
 col+=red*skullLight;
 col+=red*outline*0.25;
 // Eye sockets burn like twin internal warning LEDs.
 float eyes=exp(-length((s-vec2(-0.205,0.045))*vec2(3.7,4.0))*8.0)
           +exp(-length((s-vec2(0.205,0.045))*vec2(3.7,4.0))*8.0);
 col+=red*eyes*0.45*(0.75+0.25*sin(t*5.0));
 // Seven segmented teeth in the lower jaw.
 for(int i=0;i<7;i++){
  float x=(float(i)-3.0)*0.076;
  float tooth=1.0-smoothstep(0.005,0.018,sdBox(s-vec2(x,-0.455),vec2(0.027,0.095)));
  col+=red*tooth*mask*0.30;
 }
 // Data debris escapes the silhouette as the signal fails.
 vec2 debris=p*vec2(84.0,92.0);
 vec2 id=floor(debris);
 vec2 f=fract(debris)-0.5;
 float nearSkull=1.0-smoothstep(0.35,0.92,length(p*vec2(0.9,1.0)));
 float particle=1.0-smoothstep(0.05,0.16,length(f));
 float randomGate=step(0.94,hash2(id+floor(t*3.0)));
 col+=red*particle*randomGate*nearSkull*0.25;
 // Moving horizontal intrusion beams and controlled RGB displacement.
 float sweep=exp(-abs(p.y-0.67*sin(t*0.43))*95.0);
 float alert=step(0.92,hash(floor(t*1.7)));
 col+=red*sweep*(0.12+0.13*alert);
 float glitchLine=step(0.985,hash(floor(p.y*180.0)+floor(t*12.0)*41.0));
 col+=red*glitchLine*nearSkull*0.075;
 col*=0.94+0.06*sin(gl_FragCoord.y*1.7);
 col*=1.0-smoothstep(0.4,1.5,length(p))*0.65;
 col=vec3(1.0)-exp(-col*max(u_glow,0.0)*2.0);
 fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

precision highp float;
uniform vec2 u_resolution;
uniform float u_time, u_speed, u_glow, u_hue, u_scale;
uniform vec3 u_colorA, u_colorB;
out vec4 fragColor;
float h21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}
float box2(vec2 p,vec2 b){vec2 d=abs(p)-b;return length(max(d,0.0))+min(max(d.x,d.y),0.0);}
float seg(vec2 p,vec2 a,vec2 b){vec2 v=b-a;return length(p-a-v*clamp(dot(p-a,v)/max(dot(v,v),0.0001),0.0,1.0));}
float glyph(vec2 p,float seed){float v=0.0;for(int i=0;i<5;i++){float fi=float(i);vec2 a=vec2(h21(vec2(seed,fi))-0.5,h21(vec2(fi,seed+7.0))-0.5);vec2 b=vec2(h21(vec2(seed+19.0,fi))-0.5,h21(vec2(fi+8.0,seed))-0.5);v=max(v,1.0-smoothstep(0.035,0.09,seg(p,a,b)));}return v;}
void main(){
 vec2 uv=gl_FragCoord.xy/max(u_resolution,vec2(1.0));
 vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/max(u_resolution.y,1.0);
 p/=max(u_scale,0.3);
 float t=u_time*u_speed;
 vec3 amber=mix(u_colorA,u_colorB,0.18+0.55*u_hue);
 vec3 col=vec3(0.002,0.0022,0.0003);
 // Moving encrypted code strips, distinct from conventional full-screen matrix rain.
 vec2 g=vec2(p.x*16.0,p.y*16.0);
 float column=floor(g.x);
 float velocity=0.75+0.9*h21(vec2(column,12.0));
 float scroll=t*velocity;
 vec2 id=floor(vec2(g.x,g.y+scroll));
 vec2 cell=fract(vec2(g.x,g.y+scroll))-0.5;
 float seed=h21(id);
 float stripe=step(0.43,h21(vec2(column,3.0)));
 float symbol=glyph(cell*1.4,seed*91.0);
 float flicker=step(0.13,h21(id+floor(t*2.0)));
 float head=fract((g.y+scroll)/19.0+h21(vec2(column,6.0)));
 float trail=pow(1.0-head,3.5);
 float code=symbol*flicker*stripe*(0.08+0.7*trail);
 col+=amber*code*0.48;
 // Central hazard aperture: concentric octagonal contours and rotating security sweeps.
 vec2 q=p;
 float r=length(q);
 float ang=atan(q.y,q.x);
 float oct=cos(3.14159265/8.0)/cos(mod(ang+3.14159265/8.0,3.14159265/4.0)-3.14159265/8.0);
 float octDist=r*oct;
 float aperture=exp(-pow((octDist-0.31)*115.0,2.0));
 float ring2=exp(-pow((octDist-0.37)*95.0,2.0));
 float ring3=exp(-pow((octDist-0.44)*80.0,2.0));
 float sweepAngle=mod(ang-t*0.75+6.2831853,6.2831853);
 float scan=pow(max(0.0,cos(sweepAngle)),90.0)*smoothstep(0.09,0.18,r)*(1.0-smoothstep(0.48,0.62,r));
 float segments=step(0.53,fract(ang*16.0/6.2831853+t*0.03));
 float dash=ring3*segments;
 float center=1.0-smoothstep(0.12,0.145,r);
 float pulse=0.55+0.45*sin(t*3.2);
 col+=amber*(aperture*1.05+ring2*0.36+dash*0.4+scan*0.5)*u_glow;
 col+=mix(amber,vec3(1.0,0.97,0.7),0.35)*center*(0.028+0.045*pulse);
 // Animated yellow/black hazard chevrons around the security core.
 vec2 hz=vec2(abs(q.x),abs(q.y));
 float panel=1.0-smoothstep(0.006,0.013,box2(hz-vec2(0.0,0.52),vec2(0.9,0.026)));
 float stripePhase=fract((q.x+q.y*0.75)*19.0-t*0.22);
 float hazard=panel*step(0.5,stripePhase);
 col+=u_colorA*hazard*0.22;
 // Binary diagnostic bars and intermittent horizontal breach scans.
 float lineY=floor((p.y+0.95)*34.0);
 float bar=step(0.77,h21(vec2(lineY,17.0)))*step(0.05,abs(p.x)-0.51);
 float micro=step(fract(p.x*42.0+lineY*0.27),0.45);
 col+=u_colorB*bar*micro*0.09;
 float breach=exp(-abs(p.y-(fract(t*0.11)*2.4-1.2))*150.0);
 float breachMask=step(0.6,h21(vec2(floor(t*0.5),7.0)));
 col+=u_colorA*breach*breachMask*0.22;
 // Fine CRT texture and vignette.
 float crt=0.94+0.06*sin(gl_FragCoord.y*1.5);
 col*=crt*(1.0-0.36*smoothstep(0.35,1.25,length(p)));
 col=1.0-exp(-col*max(u_glow,0.0)*1.05);
 fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

precision highp float;
uniform vec2 u_resolution;
uniform float u_time, u_speed, u_glow, u_hue, u_scale;
